tool_input.command:
cd features/regression/step_definitions && for f in *.ts; do
  perl -0777 -ne '
    while (/\b(Given|When|Then)\(\s*\n?\s*[`'"'"'"]([^`'"'"'"]+)[`'"'"'"]/gs) {
      print "'"$f"': $1: $2\n";
    }
  ' "$f"
done > /tmp/all_steps2.txt
wc -l /tmp/all_steps2.txt
echo "--- duplicates by phrase text (ignoring Given/When/Then kind) ---"
sed -E 's/^[^:]+: (Given|When|Then): //' /tmp/all_steps2.txt | sort | uniq -d

